import { render, screen, fireEvent, act, waitFor } from '@testing-library/react'
import { expect, test, vi } from 'vitest'
import { Pagination } from './Pagination'

test('prev disabled on the first page, next on the last', () => {
  const { rerender } = render(<Pagination total={25} pageSize={10} page={1} onChange={() => {}} />)
  expect(screen.getByRole('button', { name: 'Prev' }).disabled).toBe(true)
  expect(screen.getByRole('button', { name: 'Next' }).disabled).toBe(false)
  rerender(<Pagination total={25} pageSize={10} page={3} onChange={() => {}} />)
  expect(screen.getByRole('button', { name: 'Next' }).disabled).toBe(true)
})

test('clicking a page calls onChange and marks the current page', () => {
  const onChange = vi.fn()
  render(<Pagination total={25} pageSize={10} page={2} onChange={onChange} />)
  expect(screen.getByRole('button', { name: '2' }).getAttribute('aria-current')).toBe('page')
  fireEvent.click(screen.getByRole('button', { name: '3' }))
  fireEvent.click(screen.getByRole('button', { name: 'Prev' }))
  expect(onChange.mock.calls).toEqual([[3], [1]])
})

test('empty state', () => {
  render(<Pagination total={0} pageSize={10} page={1} onChange={() => {}} />)
  expect(screen.getByText('No results')).toBeTruthy()
  expect(screen.queryByRole('button')).toBeNull()
})

