import { useState } from 'react'

export function useCounter({ initial = 0, step = 1, max = Infinity } = {}) {
  const [count, setCount] = useState(initial)
  return {
    count,
    inc: () => setCount((c) => Math.min(max, c + step)),
    dec: () => setCount((c) => c - step),
    reset: () => setCount(initial),
  }
}

tests.code:
import { renderHook, act } from '@testing-library/react'
import { expect, test } from 'vitest'
import { useCounter } from './useCounter'

test('starts at initial and counts by step', () => {
  const { result } = renderHook(() => useCounter({ initial: 5, step: 2 }))
  expect(result.current.count).toBe(5)
  act(() => result.current.inc())
  act(() => result.current.dec())
  act(() => result.current.inc())
  expect(result.current.count).toBe(7)
})

test('never goes above max, reset works', () => {
  const { result } = renderHook(() => useCounter({ max: 2 }))
  act(() => { result.current.inc(); result.current.inc(); result.current.inc() })
  expect(result.current.count).toBe(2)
  act(() => result.current.reset())
  expect(result.current.count).toBe(0)
})

test('reads new options on rerender', () => {
  const { result, rerender } = renderHook((opts) => useCounter(opts), { initialProps: { step: 1 } })
  rerender({ step: 10 })
  act(() => result.current.inc())
  expect(result.current.count).toBe(10)
})

