import { useEffect, useState } from 'react'

const defaultFetch = (city) => fetch(`/api/weather?city=${encodeURIComponent(city)}`).then((r) => r.json())

export function Weather({ city, fetchWeather = defaultFetch }) {
  const [s, setS] = useState({ status: 'loading' })
  useEffect(() => {
    let ignore = false
    setS({ status: 'loading' })
    fetchWeather(city).then(
      (d) => { if (!ignore) setS({ status: 'ok', temp: d.temp }) },
      () => { if (!ignore) setS({ status: 'error' }) },
    )
    return () => { ignore = true }
  }, [city, fetchWeather])
  if (s.status === 'loading') return <p>Loading…</p>
  if (s.status === 'error') return <p role="alert">Could not load weather</p>
  return <p>{city}: {s.temp}°C</p>
}

tests.code:
import { render, screen } from '@testing-library/react'
import { afterEach, expect, test, vi } from 'vitest'
import { Weather } from './Weather'

afterEach(() => vi.restoreAllMocks())

test('injected fake: loading then data', async () => {
  const fake = vi.fn().mockResolvedValue({ temp: 31 })
  render(<Weather city="Pune" fetchWeather={fake} />)
  expect(screen.getByText('Loading…')).toBeTruthy()
  expect(await screen.findByText('Pune: 31°C')).toBeTruthy()
  expect(fake).toHaveBeenCalledWith('Pune')
})

test('rejected request shows an alert', async () => {
  render(<Weather city="Pune" fetchWeather={vi.fn().mockRejectedValue(new Error('500'))} />)
  expect((await screen.findByRole('alert')).textContent).toBe('Could not load weather')
})

test('default uses fetch with the city in the URL', async () => {
  const spy = vi.spyOn(globalThis, 'fetch').mockResolvedValue(new Response(JSON.stringify({ temp: 20 })))
  render(<Weather city="New Delhi" />)
  expect(await screen.findByText('New Delhi: 20°C')).toBeTruthy()
  expect(spy).toHaveBeenCalledWith('/api/weather?city=New%20Delhi')
})

