import { useEffect, useState } from 'react'

export function useAsync(fn, deps) {
  const [s, setS] = useState({ status: 'loading', data: undefined, error: undefined })
  useEffect(() => {
    let ignore = false
    setS({ status: 'loading', data: undefined, error: undefined })
    fn().then(
      (data) => { if (!ignore) setS({ status: 'success', data, error: undefined }) },
      (error) => { if (!ignore) setS({ status: 'error', data: undefined, error }) },
    )
    return () => { ignore = true }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, deps)
  return s
}

tests.code:
import { renderHook, waitFor, act } from '@testing-library/react'
import { afterEach, expect, test, vi } from 'vitest'
import { useAsync } from './useAsync'

afterEach(() => vi.useRealTimers())

test('loading then success', async () => {
  const { result } = renderHook(() => useAsync(async () => 42, []))
  expect(result.current.status).toBe('loading')
  await waitFor(() => expect(result.current.status).toBe('success'))
  expect(result.current.data).toBe(42)
})

test('error state', async () => {
  const { result } = renderHook(() => useAsync(() => Promise.reject(new Error('nope')), []))
  await waitFor(() => expect(result.current.status).toBe('error'))
  expect(result.current.error.message).toBe('nope')
})

test('ignores a slow old result after deps change (fake timers)', async () => {
  vi.useFakeTimers()
  const load = (id, ms) => new Promise((r) => setTimeout(() => r('user ' + id), ms))
  const { result, rerender } = renderHook(({ id }) => useAsync(() => load(id, id === 1 ? 500 : 100), [id]), { initialProps: { id: 1 } })
  rerender({ id: 2 })
  await act(async () => { await vi.advanceTimersByTimeAsync(600) })
  expect(result.current.data).toBe('user 2')
})
